import{_ as e,a as i,c as s,ac as t}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Grafana 多数据源与面板配置","description":"Grafana 多数据源与面板配置","frontmatter":{"title":"Grafana 多数据源与面板配置","description":"Grafana 多数据源与面板配置","sources":[{"repository":"TeamDocs","file":"docs/engineering/grafana-prometheus.md"}],"showdocs":{"topics":[{"id":"metrics","title":"指标与可视化","link":"/topics/metrics/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","summary":"Grafana 多数据源与面板配置","status":"active","related":[{"title":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"指标与面板：空图、统计口径与故障复盘","link":"/systems/logging-monitoring/metrics/diagnosis","kind":"排错与诊断","scope":"general","audience":"general"},{"title":"指标：序列、标签、Counter 与直方图","link":"/systems/logging-monitoring/metrics/metric-model","kind":"知识专题","scope":"general","audience":"general"},{"title":"指标与可视化：容量、录制规则与面板发布","link":"/systems/logging-monitoring/metrics/plus/practice/operations","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application"},"next":false},"headers":[],"relativePath":"systems/logging-monitoring/metrics/plus/subjects/grafana-data-sources.md","filePath":"systems/logging-monitoring/metrics/plus/subjects/grafana-data-sources.md"}'),n={name:"systems/logging-monitoring/metrics/plus/subjects/grafana-data-sources.md"};function o(l,a,r,c,d,p){return i(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="grafana-多数据源与面板配置" tabindex="-1">Grafana 多数据源与面板配置 <a class="header-anchor" href="#grafana-多数据源与面板配置" aria-label="Permalink to &quot;Grafana 多数据源与面板配置&quot;">​</a></h1><blockquote><p>从来源文档中剥离的技术说明。示例与约束沿用原文，使用前按实际环境核对。</p></blockquote><h2 id="三、grafana-多源兼容" tabindex="-1">三、Grafana 多源兼容 <a class="header-anchor" href="#三、grafana-多源兼容" aria-label="Permalink to &quot;三、Grafana 多源兼容&quot;">​</a></h2><h3 id="_3-1-增加源数据" tabindex="-1">3.1 增加源数据 <a class="header-anchor" href="#_3-1-增加源数据" aria-label="Permalink to &quot;3.1 增加源数据&quot;">​</a></h3><ol><li>进入 Grafana 的数据源配置页面。</li><li>选择 Prometheus 源</li><li>按顺序填写配置信息</li><li>点击&quot;测试 &amp; 保存&quot;</li></ol><h3 id="_3-2-项目面板配置" tabindex="-1">3.2 项目面板配置 <a class="header-anchor" href="#_3-2-项目面板配置" aria-label="Permalink to &quot;3.2 项目面板配置&quot;">​</a></h3><h4 id="_3-2-1-增加变量" tabindex="-1">3.2.1 增加变量 <a class="header-anchor" href="#_3-2-1-增加变量" aria-label="Permalink to &quot;3.2.1 增加变量&quot;">​</a></h4><ol><li>进入面板设置，点击&quot;变量&quot;（Variables）</li><li>添加新变量： <ul><li><strong>名称（Name）</strong>：<code>DataSource</code>，与下文大小写一致。</li><li><strong>变量类型</strong>：选择数据源（Data source）</li><li><strong>数据源选项</strong>：Prometheus</li><li>按目标平台设置数据源筛选条件，实际值见公司面板配置。</li><li>点击&quot;查询&quot;可以看到预览值</li></ul></li><li>保存变量设置</li></ol><h4 id="_3-2-2-修改变量" tabindex="-1">3.2.2 修改变量 <a class="header-anchor" href="#_3-2-2-修改变量" aria-label="Permalink to &quot;3.2.2 修改变量&quot;">​</a></h4><ol><li>编辑面板中的 <code>job</code> 变量，将数据源改为使用变量：<code>${DataSource}</code></li><li>同样修改 <code>group</code> 变量</li></ol><h3 id="_3-3-修改-json-数据" tabindex="-1">3.3 修改 JSON 数据 <a class="header-anchor" href="#_3-3-修改-json-数据" aria-label="Permalink to &quot;3.3 修改 JSON 数据&quot;">​</a></h3><p>在面板的 JSON 配置中，将 <code>datasource</code> 配置修改为：</p><div class="language-json vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;datasource&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prometheus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;uid&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${DataSource}&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>将目标 Prometheus 数据源引用中的 UID（不要替换面板或其他对象的 UID）替换成 <code>${DataSource}</code>，保存面板即可。</p><h2 id="公司实践" tabindex="-1">适用范围 <a class="header-anchor" href="#公司实践" aria-label="Permalink to &quot;适用范围 {#公司实践}&quot;">​</a></h2>',15)])])}const u=e(n,[["render",o]]);export{h as __pageData,u as default};
